class SettingsScreen extends StatefulWidget { const SettingsScreen({super.key,required this.profile,required this.controller});final UserProfile profile;final ProfileController controller;@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{late ProfileVisibility _visibility;@override void initState(){super.initState();_visibility=widget.profile.visibility;}@override Widget build(BuildContext context)=>Scaffold(backgroundColor:AppColors.background,appBar:AppBar(backgroundColor:AppColors.background,title:const Text('Profil ayarları',style:TextStyle(fontWeight:FontWeight.w800))),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Profil gizliliği',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),const SizedBox(height:8),const Text('Gizli profillerde arkadaş olmayan kişiler yalnızca temel bilgileri görür.',style:TextStyle(color:AppColors.textMuted)),const SizedBox(height:16),SegmentedButton<ProfileVisibility>(segments:const[ButtonSegment(value:ProfileVisibility.public,label:Text('Herkese açık'),icon:Icon(Icons.public)),ButtonSegment(value:ProfileVisibility.friendsOnly,label:Text('Gizli'),icon:Icon(Icons.lock_outline))],selected:{_visibility},onSelectionChanged:(value)=>setState(()=>_visibility=value.first)),const SizedBox(height:24),FilledButton(onPressed:()async{await widget.controller.save(name:widget.profile.displayName,city:widget.profile.city??'',state:widget.profile.state??'',interests:widget.profile.interests,visibility:_visibility);if(mounted)Navigator.pop(context);},child:const Text('Kaydet'))]));}
